window.AUTH=window.AUTH||{};window.AUTH["83-1911"]={"d":"83-1911","id":"1984/83-1911","n":"Lowe v. Securities and Exchange Commission","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the Securities and Exchange Commission","date":"","url":"https://www.justice.gov/osg/media/223221/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/christopher-l-lowe-et-al-petitioners-v-securities-and-exchange-commission","toa":false,"n":83}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep472/usrep472181/usrep472181.pdf","tr":false,"items":[{"t":"case","label":"Citing Ohralik v. Ohio State Bar Ass'n","cite":"436 U.S. 447","y":1978,"id":"1977/76-1650","sc":1,"op":2,"sum":"The Court held that a state may constitutionally discipline a lawyer for soliciting clients in person and for financial gain under circumstances likely to pose dangers that the state has a right to prevent.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Virginia State Board of Pharmacy v. Virginia Citizen's Consumer Council, Inc.","cite":"425 U.S. 748","y":1976,"id":"1975/74-895","sc":1,"op":1,"sum":"In a 7-to-1 opinion, the Court held that the First Amendment protects willing speakers and willing listeners equally. The Court noted that in cases of commercial speech, such as price advertising, freedom of speech protections apply just as they would to noncommercial speech. Even speech that is sold for profit, or involves financial solicitations, is protected.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"SEC v. Capital Gains Research Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"op":4,"sum":"Describing the recurrent abusive practice by unethical advisory publishers known as \"scalping\".","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"Silver v. New York Stock Exchange","cite":"373 U.S. 341","y":1963,"id":"1962/150","sc":1,"sum":"The duty of self-regulation imposed upon the Exchange by the Securities Exchange Act of 1934 did not exempt it from the antitrust laws nor justify it in denying petitioners the direct-wire connections without the notice and hearing which they requested. Therefore, the Exchange's action in this case violated § 1 of the Sherman Act, and the Exchange is liable to petitioners under §§ 4 and 16 of the Clayton Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Marketlines, Inc. v. SEC","cite":"384 F.2d 264","y":1967,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/384/264/","by":{"0":""}},{"t":"case","label":"SEC v. Texas Gulf Sulphur Co.","cite":"401 F.2d 833","y":1968,"court":"CA2","url":"https://www.courtlistener.com/c/F.2d/401/833/","op":1,"by":{"0":""}},{"t":"case","label":"Mills v. Electric Auto-Lite Co.","cite":"396 U.S. 375","y":1970,"id":"1969/64","sc":1,"sum":"Petitioners, minority shareholders of respondent Electric Auto-Lite Co., brought this action derivatively and on behalf of minority shareholders as a class to set aside a merger of Auto-Lite and the Mergenthaler Linotype Co. (which before the merger owned over half of Auto-Lite's stock). Petitioners charged that the proxy solicitation for the merger by Auto-Lite's management was materially misleading and violated § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"American Column & Lumber Co. v. United States","cite":"257 U.S. 377","y":1921,"id":"scdb/1921-040","sc":1,"sum":"An “ Open Competition Plan ” under, which manufacturers of one-third of the hardwood output of the country exchanged-full and minute disclosures of the details of their business, including stocks-, on hand, production, shipments, prices, namest of purchasers, etc., and their views on future market conditions, by means of reports and letters from the several members to a central office and distribution to them …","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"NLRB v. Gissel Packing Co.","cite":"395 U.S. 575","y":1969,"id":"1968/573","sc":1,"sum":"In Nos. 573 and 691, Unions waged organizational campaigns, obtained authorization cards from a majority of employees in the appropriate bargaining units, and demanded recognition by the employers. The employers refused to bargain, on the ground that the cards were inherently unreliable, and carried out vigorous antiunion campaigns. In one instance the Union did not seek a representation election but filed unfair …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"National Society of Professional Engineers v. United States","cite":"435 U.S. 679","y":1978,"id":"1977/76-1767","sc":1,"sum":"The United States brought this civil antitrust suit against petitioner, the National Society of Professional Engineers, alleging that petitioner's canon of ethics prohibiting its members from submitting competitive bids for engineering services suppressed competition in violation of § 1 of the Sherman Act. Petitioner defended on the ground, inter a~ia, that under the Rule of Reason the canon was justified because it …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Court in Giboney v. Empire Storage & Ice Co.","cite":"336 U.S. 490","y":1949,"id":"scdb/1948-056","sc":1,"op":1,"sum":"The state law, as construed and applied in this case, does not violate the Federal Constitution, and the judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Watson v. Maryland","cite":"218 U.S. 173","y":1910,"id":"scdb/1909-173","sc":1,"sum":"The decision of the state court that an offense under a statute did not depend on conditions as to notice contained in another statute is conclusive on this court; and one convicted in a state court is not denied due process of law by reason of such construction.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Dent v. West Virginia","cite":"129 U.S. 114","y":1889,"id":"scdb/1888-092","sc":1,"op":1,"sum":"The statute of West Virginia (§§ 9 and 15, chapter 93, 1882) which requires every practitioner ofmedicine in the State to. obtain a certificate from the State Board of Health that he is a graduate of a reputable medi-._ cal college in the school of medicine to which hebelongs; or that he has. practised medicine in the State continuously for ten years prior to March 8, 1881; of that he has been found upon examination …","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Goldfarb v. Virginia State Bar","cite":"421 U.S. 773","y":1975,"id":"1974/74-70","sc":1,"sum":"The minimumfee schedule, as published by the County Bar Association and enforced by the State Bar, violates § 1 of the Sherman Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Barsky v. Board of Regents","cite":"347 U.S. 442","y":1954,"id":"scdb/1953-067","sc":1,"sum":"The New York law, on its face or as so construed and applied, does not violate the Due Process Clause of the Fourteenth Amendment. Pp. 443-456. _ (a) The decision of the highest state court that a violation of 2 U. S. C. § 192, though not a crime under New York law, was a \"crime\" within the meaning of § 6514-2 (b) of the State Education Law, is conclusive here.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Board of Regents v. Roth","cite":"408 U.S. 564","id":"1971/71-162","sc":1,"sum":"The court held 5-3 that Roth had no protected interest in continued employment, as he had completed his contracted term, and therefore was no Fourteenth Amendment protection.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Connick v. Myers","cite":"461 U.S. 138","y":1983,"id":"1982/81-1251","sc":1,"sum":"The Supreme Court held that speech of public employees is generally only protected when they speak on matters of public concern. Meyers’ speech only dealt with personal and internal office issues. The district court also erred in placing too high of a burden on Connick to show that Meyers’ speech substantially interfered with the operation of the office.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Pickering v. Board of Education","cite":"391 U.S. 563","y":1968,"id":"1967/510","sc":1,"sum":"Justice Thurgood Marshall wrote the 8-1 majority opinion holding that Pickering’s dismissal violated his First Amendment right to free speech. The Supreme Court noted that similar speech is not protected if it contains false statements knowingly or recklessly made. There was no evidence that Pickering’s statements were knowingly false or reckless.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Donaldson v. Read Magazine, Inc.","cite":"333 U.S. 178","y":1948,"id":"scdb/1947-045","sc":1,"sum":"1. Where the Postmaster General has issued a fraud order under 39 U. S. C. §§ 259., 732, and later concludes that it is broader than necessary to protect the public, he has power to modify the order so as to make it less inclusive-even though there be pending in this Court at the time a review of a judgment of a federal court of appeals affirming a judgment of a district court enjoining enforcement of the order.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. O'Brien","cite":"391 U.S. 367","y":1968,"id":"1967/232","sc":1,"sum":"The Court found that it was not an infringement on one's First Amendment rights to criminalize burning a draft card.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Halsted v. SEC","cite":"182 F.2d 660","url":"https://www.courtlistener.com/c/F.2d/182/660/","by":{"0":""}},{"t":"case","label":"SEC v. Suter","cite":"732 F.2d 1294","y":1984,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/732/1294/","op":1,"by":{"0":""}},{"t":"case","label":"Savage v. CFTC","cite":"548 F.2d 192","y":1977,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/548/192/","by":{"0":""}},{"t":"case","label":"Metromedia, Inc. v. San Diego","cite":"453 U.S. 490","y":1981,"id":"1980/80-195","sc":1,"sum":"However the Court held that affording \"a greater degree of protection to commercial than to noncommercial speech\" reversed the long-standing Court precedent to show greater deference to noncommercial speech.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Minneapolis Star & Tribune Co. v. Minnesota Commissioner of Revenue","cite":"460 U.S. 575","y":1983,"id":"1982/81-1839","sc":1,"sum":"The Court held that while the First Amendment did not prohibit all regulation of the press, Minnesota had \"created a special tax that applie[d] only to certain publications protected by the First Amendment.\" Noting that there was \"substantial evidence that differential taxation of the press would have troubled the Framers of the First Amendment,\" the Court held that when states single out the press \"the threat of burdensome taxes becomes acute.\" The Court concluded that \"recognizing a power in the State not only to single out the press but also to tailor the tax so that it singles out a few members of the press presents such a potential for abuse that no interest suggested by Minnesota can justify the scheme.\".","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Grosjean v. American Press Co.","cite":"297 U.S. 233","y":1936,"id":"scdb/1935-086","sc":1,"sum":"1. As respects the amount in controversy, the District Court has jurisdiction of a suit where the requisite value is involved as to each of several plaintiffs though not involved as to others.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"SEC v. Shapiro","cite":"494 F.2d 1301","y":1974,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/494/1301/","by":{"0":""}},{"t":"case","label":"Mitchell v. Pidcock","cite":"299 F.2d 281","y":1962,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/299/281/","by":{"0":""}},{"t":"case","label":"SEC v. Culpepper","cite":"270 F.2d 241","y":1959,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/270/241/","by":{"0":""}},{"t":"case","label":"Pittsburgh Press Co. v. Pittsburgh Comm'n on Human Relations","cite":"413 U.S. 376","y":1973,"id":"1972/72-419","sc":1,"sum":"The Court held that an ordinance that forbids newspapers to advertise employment opportunities in gender-designated columns does not violate the freedom of press guaranteed by the First Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Again, in Lorain Journal Co. v. United States","cite":"342 U.S. 143","y":1951,"id":"scdb/1951-016","sc":1,"sum":"The publisher was engaged in an attempt to monopolize interstate commerce, in violation of § 2 of the Sherman Antitrust Act, and was properly enjoined under § 4 from continuing the attempt.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Bates v. State Bar","cite":"433 U.S. 350","y":1977,"id":"1976/76-316","sc":1,"op":1,"sum":"The Court found that the rule violated the First and Fourteenth Amendments. Justice Blackmun argued that commercial speech does merit First Amendment protection given the important functions it serves in society, such as providing consumers with information about services and products, and helping to allocate resources in the American system of free-enterprise.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Abood v. Detroit Board of Education","cite":"431 U.S. 209","y":1977,"id":"1976/75-1153","sc":1,"sum":"A Michigan statute authorizing union representation of local governmental employees permits an \"agency shop\" arrangement, whereby every employee represented by a union, even though not a union member, must pay to the union, as a condition of employment, a service charge equal in amount to union dues. Appellant teachers filed actions (later consolidated) m Michigan state court against appellee Detroit Board of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Central Hudson Gas & Electric Corp. v. Public Service Comm'n","cite":"447 U.S. 557","y":1980,"id":"1979/79-565","sc":1,"op":1,"sum":"The Court overruled the Court of Appeals of New York and held that the New York's ban violated the right to commercial speech. Writing for the majority, Justice Lewis F. Powell cited the protections for \"commercial speech from unwarranted governmental regulation\" set forth in Virginia Pharmacy Board v. Virginia Citizens Consumer Council .","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Consolidated Edison Co. v. Public Service Comm'n","cite":"447 U.S. 530","y":1980,"id":"1979/79-134","sc":1,"op":1,"sum":"An order of appellee New York Public Service Commission that prohibits the inclusion by appellant (and other public utility companies) in monthly bills of inserts discussing controversial issues of public policy directly infringes the freedom of speech protected by the First and Fourteenth Amendments and thus is invalid. Cf. First National Bank of Boston v. Bellotti, 435 U. S. 765.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Readers Digest Ass'n","cite":"662 F.2d 955","y":1981,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/662/955/","by":{"0":""}},{"t":"case","label":"City of New Orleans v. Dukes","cite":"427 U.S. 297","y":1976,"id":"1975/74-775","sc":1,"sum":"A New Orleans ordinance prohibits pushcart food sales in the Vieux Carre, or French Quarter, but by a \"grandfather provision\" exempts pushcart vendors who had operated in the Quarter for eight years. Appellee, who had conducted a pushcart business there for less than that time, brought suit in the District Court challenging the application of the grandfather provision as a denial of equal protection. The District …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Hodel v. Indiana","cite":"452 U.S. 314","y":1981,"id":"1980/80-231","sc":1,"sum":"The Act is not vulnerable to appellees' pre-enforcement constitutional challenge.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Schweiker v. Wilson","cite":"450 U.S. 221","y":1981,"id":"1980/79-1380","sc":1,"sum":"Appellees' rights to equal protection were not violated by denying them SSI benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Police Dep't v. Mosley","cite":"408 U.S. 92","y":1972,"id":"1971/70-87","sc":1,"sum":"The exemption for labor picketing violated the equal protection clause. Government regulation of message content is presumed unconstitutional unless there are compelling justifications. And regulations that selectively exclude speakers from a public forum must undergo careful judicial examination to ensure the minimal degree of furthering an important government interest.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Williams v. Rhodes","cite":"393 U.S. 23","y":1968,"id":"1968/543","sc":1,"sum":"The Court found that Ohio failed to show a compelling interest in limiting the parties' ballot access. The Court concluded that Ohio's restrictions gave the two major parties a \"total monopoly\" and imposed a significant, unequal burden on minority groups.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Williamson v. Lee Optical Co.","cite":"348 U.S. 483","y":1955,"id":"1940-1955/348us483","sc":1,"sum":"A case in which the Court upheld an Oklahoma law regulating the fitting of lenses for eyeglasses where the challengers could not prove that the law had no rational relationship to legitimate state objectives.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Vance v. Bradley","cite":"440 U.S. 93","y":1979,"id":"1978/77-1254","sc":1,"sum":"The Court emphasized the distinction between the Civil Service and Foreign Service, and the \"special attention\" paid to the Foreign Service by Congress.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Duke Power Co. v. Carolina Environmental Study Group, Inc.","cite":"438 U.S. 59","y":1978,"id":"1977/77-262","sc":1,"sum":"The Price-Anderson Act (Act), having the dual purpose of protecting the public and encouraging the development of the nuclear energy industry, imposes a $560 million limitation on liability for nuclear accidents resulting from the operation of federally licensed private nuclear power plants, requires those indemnified by the $560 million fund established under the Act to waive all legal defenses in the event of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States Railroad Retirement Board v. Fritz","cite":"449 U.S. 166","y":1980,"id":"1980/79-870","sc":1,"sum":"The Court held that laws may create classifications that are not elegant or “artfully drawn” but that are not unconstitutional. The Constitution would allow Congress to deny windfall benefits to all employees, therefore it was not unconstitutional to deny them to some.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Dandridge v. Willaims","cite":"397 U.S. 471","y":1970,"id":"1969/131","sc":1,"sum":"The Court concluded that the Maryland provision violated neither the Social Security Act nor the Equal Protection Clause.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Lindsley v. Natural Carbonic Gas Co.","cite":"220 U.S. 61","y":1911,"id":"scdb/1910-088","sc":1,"sum":"Courts of the United States must accept the construction put upon a state statute by the highest court of the State; and, in determining the constitutionality of a state statute, this court is not concerned with provisions thereof which the highest court of the State has declared invalid.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"SEC v. Wall Street Transcript Corp.","cite":"422 F.2d 1371","url":"https://www.courtlistener.com/c/F.2d/422/1371/","op":6,"by":{"0":""}},{"t":"case","label":"United States v. Clark","cite":"454 U.S. 555","y":1982,"id":"1981/80-1121","sc":1,"sum":"Section 5334(b) does not apply to WS employees promoted to GS positions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Schweiker v. Hogan","cite":"457 U.S. 569","y":1982,"id":"1981/81-213","sc":1,"sum":"Section 1903(f) of the Social Security Act provides that federal reimbursement to States electing to provide Medicaid benefits to the \"medically needy\" is available only if the income of those persons, after deduction of incurred medical expenses, is less than 133 14% of the state Aid to Families With Dependent Children (AFDC) payment level. Section 1903(f) specifically excepts from this rule the \"categorically …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"sum":"Alleging that they were defrauded by misrepresentations in a registration statement and prospectus for certain securities, purchasers of such securities brought a class action in Federal District Court against most of the participants in the offering, seeking recovery under § 10(b) of the Securities Exchange Act of 1934 (1934 Act), which makes it unlawful for \"any\" person to use \"any\" manipulative or deceptive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith v. Curran","cite":"456 U.S. 353","y":1982,"id":"1981/80-203","sc":1,"sum":"A private party may maintain an action for damages caused by a violation of the CEA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":""}},{"t":"case","label":"NAACP v. Federal Power Comm'n","cite":"425 U.S. 662","y":1976,"id":"1975/74-1608","sc":1,"sum":"The National Association for the Advancement of Colored People and various other organizations petitioned the Fcderal Power Commission (FPC) to issue a rule \"requiring equal employment opportunity and nondiscrimination in the employment practices of its regulatees.\" The FPC refused, holding that it had no Jurisdiction to issue such a rule. On petition for review, the Court of Appeals, while agreeing that the FPC …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"National Broadcasting Co. v. United States","cite":"319 U.S. 190","y":1943,"id":"scdb/1942-051","sc":1,"sum":"1. The regulatory powers of the Federal Communications Commission are not limited to the engineering and technical aspects of radio communication.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"New York Central Securities Corp. v. United States","cite":"287 U.S. 12","y":1932,"id":"scdb/1932-039","sc":1,"sum":"(.1) Under subdivision (2) the Commission may authorize a carrier that already controls others by stock ownership, to have control also by lease, for the purpose of securing greater economy and efficiency of operation. The disjunctive phrasing, \"either under a lease or by purchase of stock,\" does not mean that one method must be exclusive of the other. Pp. 22-23. (2) The extent of control allowable by the Commission …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Young v. American Mini Theaters, Inc.","cite":"427 U.S. 50","y":1976,"id":"1975/75-312","sc":1,"sum":"The court reversed the Sixth Circuit and held that Detroit's ordinances were reasonable, and although erotic material could not be completely suppressed, Detroit had adequate reasons to restrict the distribution of such material.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"op":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. Harriss","cite":"347 U.S. 612","y":1954,"id":"scdb/1953-080","sc":1,"by":{"0":""}},{"t":"case","label":"New York Times Co. v. United States","cite":"403 U.S. 713","y":1971,"id":"1970/1873","sc":1,"op":1,"sum":"The Court found that the use of \"prior restraint\" by President Nixon on a New York Times article about activities in Vietnam was an unconstitutional violation of the First Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Southeastern Promotions, Ltd. v. Conrad","cite":"420 U.S. 546","y":1975,"id":"1974/73-1004","sc":1,"sum":"The Court reversed the Sixth Circuit and held that Chattanooga's denial of the Southeastern's request was a \"prior restraint,\" an attempt to censor speech and prevent it from reaching the public.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Freedman v. Maryland","cite":"380 U.S. 51","y":1961,"id":"1964/69","sc":1,"sum":"The Court found the Maryland law to be invalid. The Court decision reflected a concern that the statute provides the danger of \"unduly suppressing protected expression.\" The board was allowed overly broad licensing discretion with a lack of statutory provisions for judicial participation in the the procedure to prohibit a film.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Cornflower Entertainment, Inc. v. Salt Lake City Corp.","cite":"485 F. Supp. 777","y":1980,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp./485/777/","by":{"0":""}},{"t":"case","label":"Citizen Publishing Co. v. United States","cite":"394 U.S. 131","y":1969,"id":"1968/243","sc":1,"sum":"In 1940 the only two daily newspapers in Tucson, the Citizen, an evening paper, and the Star, a daily and Sunday paper, negotiated a joint operating agreement, which was to run for 25 years. Prior thereto the papers had been vigorous competitors. The agreement provided that each paper was to retain its news and editorial departments and corporate identity, but that generally business operations were to be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Breard v. Alexandria","cite":"341 U.S. 622","y":1951,"id":"scdb/1950-092","sc":1,"sum":"A so-called \"Green River ordinance\" of a municipality forbids the practice of going in and upon private residences for the purpose of soliciting orders for the sale of goods, without prior consent of the owners or occupants. Appellant, representing a foreign corporation, was engaged in door-to-door soliciting of subscriptions for nationally known magazines and periodicals. Subscriptions were acknowledged by a card …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Oklahoma Press Publishing Co. v. Walling","cite":"327 U.S. 186","y":1946,"id":"scdb/1945-112","sc":1,"op":1,"sum":"1. The Fair Labor Standards Act, as applied to the business of publishing and distributing newspapers, does not violate the First or Fifth Amendment or exceed the power of Congress under the Commerce Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Associated Press v. United States","cite":"326 U.S. 1","y":1945,"id":"1940-1955/326us1","sc":1,"sum":"in gathering and distributing news in interstate and foreign commerce, prohibited service of AP news to non-members, prohibited members from furnishing spontaneous news to non-members, and empowered members to block membership applications of competitors. A contract between AP and a Canadian press association obligated both to furnish news exclusively to each other. Charging inter clia that the by-laws and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Associated Press v. NLRB","cite":"301 U.S. 103","y":1937,"id":"scdb/1936-095","sc":1,"sum":"engaged in interstate commerce within the meaning of the National Labor Relations Act and Constitution, Art. I, § 8.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"SEC v. McGoff","cite":"647 F.2d 185","url":"https://www.courtlistener.com/c/F.2d/647/185/","by":{"0":""}},{"t":"case","label":"Zweig v. Hearst Corp.","cite":"594 F.2d 1261","y":1979,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/594/1261/","op":1,"by":{"0":""}},{"t":"case","label":"Branzburg v. Hayes","cite":"408 U.S. 665","y":1972,"id":"1971/70-85","sc":1,"op":1,"sum":"The Court held that requiring reporters to testify before a grand jury does not violate freedom of press or speech in the First Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"First National Bank v. Bellotti","cite":"435 U.S. 765","y":1978,"id":"1977/76-1172","sc":1,"op":25,"sum":"The Court held that the right to attempt to influence the outcomes of elections is one of the primary rights the First Amendment was meant to protect. If this form of speech came from a person rather than a corporation, there would be no question about whether it was protected speech.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Thornhill v. Alabama","cite":"310 U.S. 88","y":1940,"id":"1940-1955/310us88","sc":1,"sum":"In an 8-to-1 decision, the Court held that Section 3448 of the Alabama State Code was facially invalid.","sumSrc":"Oyez","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 80b-3","url":"https://www.law.cornell.edu/uscode/text/15/80b-3","subs":["(c)"],"stext":{"head":"§80b–3. Registration of investment advisers","paras":[[0,"(a) Necessity of registration"],[0,"Except as provided in subsection (b) and section 80b–3a of this title, it shall be unlawful for any investment adviser, unless registered under this section, to make use of the mails or any means or instrumentality of interstate commerce in connection with his or its business as an investment adviser."],[0,"(b) Investment advisers who need not be registered"],[0,"The provisions of subsection (a) shall not apply to—"],[1,"(1) any investment adviser, other than an investment adviser who acts as an investment adviser to any private fund, all of whose clients are residents of the State within which such investment adviser maintains his or its principal office and place of business, and who does not furnish advice or issue analyses or reports with respect to securities listed or admitted to unlisted trading privileges on any national securities exchange;"],[1,"(2) any investment adviser whose only clients are insurance companies;"],[1,"(3) any investment adviser that is a foreign private adviser;"],[1,"(4) any investment adviser that is a charitable organization, as defined in section 80a–3(c)(10)(D) of this title, or is a trustee, director, officer, employee, or volunteer of such a charitable organization acting within the scope of such person's employment or duties with such organization, whose advice, analyses, or reports are provided only to one or more of the following:"],[2,"(A) any such charitable organization;"],[2,"(B) a fund that is excluded from the definition of an investment company under section 80a–3(c)(10)(B) of this title; or"],[2,"(C) a trust or other donative instrument described in section 80a–3(c)(10)(B) of this title, or the trustees, administrators, settlors (or potential settlors), or beneficiaries of any such trust or other instrument;"],[1,"(5) any plan described in section 414(e) of title 26, any person or entity eligible to establish and maintain such a plan under title 26, or any trustee, director, officer, or employee of or volunteer for any such plan or person, if such person or entity, acting in such capacity, provides investment advice exclusively to, or with respect to, any plan, person, or entity or any company, account, or fund that is excluded from the definition of an investment company under section 80a–3(c)(14) of this title;"],[1,"(6)(A) any investment adviser that is registered with the Commodity Futures Trading Commission as a commodity trading advisor whose business does not consist primarily of acting as an investment adviser, as defined in section 80b–2(a)(11) of this title, and that does not act as an investment adviser to—"],[2,"(i) an investment company registered under subchapter I of this chapter; or"],[2,"(ii) a company which has elected to be a business development company pursuant to section 80a–53 of this title and has not withdrawn its election; or"],[1,"(B) any investment adviser that is registered with the Commodity Futures Trading Commission as a commodity trading advisor and advises a private fund, provided that, if after July 21, 2010, the business of the advisor should become predominately the provision of securities-related advice, then such adviser shall register with the Commission;"],[1,"(7) any investment adviser, other than any entity that has elected to be regulated or is regulated as a business development company pursuant to section 80a–53 of this title, who solely advises—"],[2,"(A) small business investment companies that are licensees under the Small Business Investment Act of 1958 [15 U.S.C. 661 et seq.];"],[2,"(B) entities that have received from the Small Business Administration notice to proceed to qualify for a license as a small business investment company under the Small Business Investment Act of 1958, which notice or license has not been revoked; or"],[2,"(C) applicants that are affiliated with 1 or more licensed small business investment companies described in subparagraph (A) and that have applied for another license under the Small Business Investment Act of 1958, which application remains pending; or"],[1,"(8) any investment adviser, other than an entity that has elected to be regulated or is regulated as a business development company pursuant to section 80a–53 of this title, who solely advises—"],[2,"(A) rural business investment companies (as defined in section 2009cc of title 7); or"],[2,"(B) companies that have submitted to the Secretary of Agriculture an application in accordance with section 2009cc–3(b) of title 7 that—"],[3,"(i) have received from the Secretary of Agriculture a letter of conditions, which has not been revoked; or"],[3,"(ii) are affiliated with 1 or more rural business investment companies described in subparagraph (A)."],[0,"(c) Procedure for registration; filing of application; effective date of registration; amendment of registration"],[0,"(1) An investment adviser, or any person who presently contemplates becoming an investment adviser, may be registered by filing with the Commission an application for registration in such form and containing such of the following information and documents as the Commission, by rule, may prescribe as necessary or appropriate in the public interest or for the protection of investors:"],[1,"(A) the name and form of organization under which the investment adviser engages or intends to engage in business; the name of the State or other sovereign power under which such investment adviser is organized; the location of his or its principal office, principal place of business, and branch offices, if any; the names and addresses of his or its partners, officers, directors, and persons performing similar functions or, if such an investment adviser be an individual, of such individual; and the number of his or its employees;"],[1,"(B) the education, the business affiliations for the past ten years, and the present business affiliations of such investment adviser and of his or its partners, officers, directors, and persons performing similar functions and of any controlling person thereof;"],[1,"(C) the nature of the business of such investment adviser, including the manner of giving advice and rendering analyses or reports;"],[1,"(D) a balance sheet certified by an independent public accountant and other financial statements (which shall, as the Commission specifies, be certified);"],[1,"(E) the nature and scope of the authority of such investment adviser with respect to clients' funds and accounts;"],[1,"(F) the basis or bases upon which such investment adviser is compensated;"],[1,"(G) whether such investment adviser, or any person associated with such investment adviser, is subject to any disqualification which would be a basis for denial, suspension, or revocation of registration of such investment adviser under the provisions of subsection (e) of this section; and"],[1,"(H) a statement as to whether the principal business of such investment adviser consists or is to consist of acting as investment adviser and a statement as to whether a substantial part of the business of such investment adviser, consists or is to consist of rendering investment supervisory services."],[0,"(2) Within forty-five days of the date of the filing of such application (or within such longer period as to which the applicant consents) the Commission shall—"],[1,"(A) by order grant such registration; or"],[1,"(B) institute proceedings to determine whether registration should be denied. Such proceedings shall include notice of the grounds for denial under consideration and opportunity for hearing and shall be concluded within one hundred twenty days of the date of the filing of the application for registration. At the conclusion of such proceedings the Commission, by order, shall grant or deny such registration. The Commission may extend the time for conclusion of such proceedings for up to ninety days if it finds good cause for such extension and publishes its reasons for so finding or for such longer period as to which the applicant consents."],[0,"The Commission shall grant such registration if the Commission finds that the requirements of this section are satisfied and that the applicant is not prohibited from registering as an investment adviser under section 80b–3a of this title. The Commission shall deny such registration if it does not make such a finding or if it finds that if the applicant were so registered, its registration would be subject to suspension or revocation under subsection (e) of this section."],[0,"(d) Other acts prohibited by subchapter"],[0,"Any provision of this subchapter (other than subsection (a) of this section) which prohibits any act, practice, or course of business if the mails or any means or instrumentality of interstate commerce are used in connection therewith shall also prohibit any such act, practice, or course of business by any investment adviser registered pursuant to this section or any person acting on behalf of such an investment adviser, irrespective of any use of the mails or any means or instrumentality of interstate commerce in connection therewith."],[0,"(e) Censure, denial, or suspension of registration; notice and hearing"],[0,"The Commission, by order, shall censure, place limitations on the activities, functions, or operations of, suspend for a period not exceeding twelve months, or revoke the registration of any investment adviser if it finds, on the record after notice and opportunity for hearing, that such censure, placing of limitations, suspension, or revocation is in the public interest and that such investment adviser, or any person associated with such investment adviser, whether prior to or subsequent to becoming so associated—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80b-3?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§80b–3. Registration of investment advisers","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 80b-2","url":"https://www.law.cornell.edu/uscode/text/15/80b-2","subs":["(a)(11)(D)"],"stext":{"head":"§80b–2. Definitions","paras":[[0,"(a) In general"],[0,"When used in this subchapter, unless the context otherwise requires, the following definitions shall apply:"],[1,"(1) \"Assignment\" includes any direct or indirect transfer or hypothecation of an investment advisory contract by the assignor or of a controlling block of the assignor's outstanding voting securities by a security holder of the assignor; but if the investment adviser is a partnership, no assignment of an investment advisory contract shall be deemed to result from the death or withdrawal of a minority of the members of the investment adviser having only a minority interest in the business of the investment adviser, or from the admission to the investment adviser of one or more members who, after such admission, shall be only a minority of the members and shall have only a minority interest in the business."],[1,"(2) \"Bank\" means (A) a banking institution organized under the laws of the United States or a Federal savings association, as defined in section 1462(5) of title 12, (B) a member bank of the Federal Reserve System, (C) any other banking institution, savings association, as defined in section 1462(4) of title 12, or trust company, whether incorporated or not, doing business under the laws of any State or of the United States, a substantial portion of the business of which consists of receiving deposits or exercising fiduciary powers similar to those permitted to national banks under the authority of the Comptroller of the Currency, and which is supervised and examined by State or Federal authority having supervision over banks or savings associations, and which is not operated for the purpose of evading the provisions of this subchapter, and (D) a receiver, conservator, or other liquidating agent of any institution or firm included in clauses (A), (B), or (C) of this paragraph."],[1,"(3) The term \"broker\" has the same meaning as given in section 3 of the Securities Exchange Act of 1934 [15 U.S.C. 78c]."],[1,"(4) \"Commission\" means the Securities and Exchange Commission."],[1,"(5) \"Company\" means a corporation, a partnership, an association, a joint-stock company, a trust, or any organized group of persons, whether incorporated or not; or any receiver, trustee in a case under title 11, or similar official, or any liquidating agent for any of the foregoing, in his capacity as such."],[1,"(6) \"Convicted\" includes a verdict, judgment, or plea of guilty, or a finding of guilt on a plea of nolo contendere, if such verdict, judgment, plea, or finding has not been reversed, set aside, or withdrawn, whether or not sentence has been imposed."],[1,"(7) The term \"dealer\" has the same meaning as given in section 3 of the Securities Exchange Act of 1934 [15 U.S.C. 78c], but does not include an insurance company or investment company."],[1,"(8) \"Director\" means any director of a corporation or any person performing similar functions with respect to any organization, whether incorporated or unincorporated."],[1,"(9) \"Exchange\" means any organization, association, or group of persons, whether incorporated or unincorporated, which constitutes, maintains, or provides a market place or facilities for bringing together purchasers and sellers of securities or for otherwise performing with respect to securities the functions commonly performed by a stock exchange as that term is generally understood, and includes the market place and the market facilities maintained by such exchange."],[1,"(10) \"Interstate commerce\" means trade, commerce, transportation, or communication among the several States, or between any foreign country and any State, or between any State and any place or ship outside thereof."],[1,"(11) \"Investment adviser\" means any person who, for compensation, engages in the business of advising others, either directly or through publications or writings, as to the value of securities or as to the advisability of investing in, purchasing, or selling securities, or who, for compensation and as part of a regular business, issues or promulgates analyses or reports concerning securities; but does not include (A) a bank, or any bank holding company as defined in the Bank Holding Company Act of 1956 [12 U.S.C. 1841 et seq.] which is not an investment company, except that the term \"investment adviser\" includes any bank or bank holding company to the extent that such bank or bank holding company serves or acts as an investment adviser to a registered investment company, but if, in the case of a bank, such services or actions are performed through a separately identifiable department or division, the department or division, and not the bank itself, shall be deemed to be the investment adviser; (B) any lawyer, accountant, engineer, or teacher whose performance of such services is solely incidental to the practice of his profession; (C) any broker or dealer whose performance of such services is solely incidental to the conduct of his business as a broker or dealer and who receives no special compensation therefor; (D) the publisher of any bona fide newspaper, news magazine or business or financial publication of general and regular circulation; (E) any person whose advice, analyses or reports relate to no securities other than securities which are direct obligations of or obligations guaranteed as to principal or interest by the United States, or securities issued or guaranteed by corporations in which the United States has a direct or indirect interest which shall have been designated by the Secretary of the Treasury, pursuant to section 3(a)(12) of the Securities Exchange Act of 1934 [15 U.S.C. 78c(a)(12)], as exempted securities for the purposes of that Act [15 U.S.C. 78a et seq.]; (F) any nationally recognized statistical rating organization, as that term is defined in section 3(a)(62) of the Securities Exchange Act of 1934 [15 U.S.C. 78c(a)(62)], unless such organization engages in issuing recommendations as to purchasing, selling, or holding securities or in managing assets, consisting in whole or in part of securities, on behalf of others;; 1 (G) any family office, as defined by rule, regulation, or order of the Commission, in accordance with the purposes of this subchapter; or (H) such other persons not within the intent of this paragraph, as the Commission may designate by rules and regulations or order."],[1,"(12) \"Investment company\", affiliated person, and \"insurance company\" have the same meanings as in the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.]. \"Control\" means the power to exercise a controlling influence over the management or policies of a company, unless such power is solely the result of an official position with such company."],[1,"(13) \"Investment supervisory services\" means the giving of continuous advice as to the investment of funds on the basis of the individual needs of each client."],[1,"(14) \"Means or instrumentality of interstate commerce\" includes any facility of a national securities exchange."],[1,"(15) \"National securities exchange\" means an exchange registered under section 6 of the Securities Exchange Act of 1934 [15 U.S.C. 78f]."],[1,"(16) \"Person\" means a natural person or a company."],[1,"(17) The term \"person associated with an investment adviser\" means any partner, officer, or director of such investment adviser (or any person performing similar functions), or any person directly or indirectly controlling or controlled by such investment adviser, including any employee of such investment adviser, except that for the purposes of section 80b–3 of this title (other than subsection (f) thereof), persons associated with an investment adviser whose functions are clerical or ministerial shall not be included in the meaning of such term. The Commission may by rules and regulations classify, for the purposes of any portion of portions of this subchapter, persons, including employees controlled by an investment adviser."],[1,"(18) \"Security\" means any note, stock, treasury stock, security future, bond, debenture, evidence of indebtedness, certificate of interest or participation in any profit-sharing agreement, collateral-trust certificate, preorganization certificate or subscription, transferable share, investment contract, voting-trust certificate, certificate of deposit for a security, fractional undivided interest in oil, gas, or other mineral rights, any put, call, straddle, option, or privilege on any security (including a certificate of deposit) or on any group or index of securities (including any interest therein or based on the value thereof), or any put, call, straddle, option, or privilege entered into on a national securities exchange relating to foreign currency, or, in general, any interest or instrument commonly known as a \"security\", or any certificate of interest or participation in, temporary or interim certificate for, receipt for, guaranty of, or warrant or right to subscribe to or purchase any of the foregoing."],[1,"(19) \"State\" means any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, or any other possession of the United States."],[1,"(20) \"Underwriter\" means any person who has purchased from an issuer with a view to, or sells for an issuer in connection with, the distribution of any security, or participates or has a direct or indirect participation in any such undertaking, or participates or has a participation in the direct or indirect underwriting of any such undertaking; but such term shall not include a person whose interest is limited to a commission from an underwriter or dealer not in excess of the usual and customary distributor's or seller's commission. As used in this paragraph the term \"issuer\" shall include in addition to an issuer, any person directly or indirectly controlling or controlled by the issuer, or any person under direct or indirect common control with the issuer."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80b-2?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§80b–2. Definitions","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 79z-4","url":"https://www.law.cornell.edu/uscode/text/15/79z-4","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 80b-1","url":"https://www.law.cornell.edu/uscode/text/15/80b-1","stext":{"head":"§80b–1. Findings","paras":[[0,"Upon the basis of facts disclosed by the record and report of the Securities and Exchange Commission made pursuant to section 79z–4 1 of this title, and facts otherwise disclosed and ascertained, it is found that investment advisers are of national concern, in that, among other things—"],[1,"(1) their advice, counsel, publications, writings, analyses, and reports are furnished and distributed, and their contracts, subscription agreements, and other arrangements with clients are negotiated and performed, by the use of the mails and means and instrumentalities of interstate commerce;"],[1,"(2) their advice, counsel, publications, writings, analyses, and reports customarily relate to the purchase and sale of securities traded on national securities exchanges and in interstate over-the-counter markets, securities issued by companies engaged in business in interstate commerce, and securities issued by national banks and member banks of the Federal Reserve System; and"],[1,"(3) the foregoing transactions occur in such volume as substantially to affect interstate commerce, national securities exchanges, and other securities markets, the national banking system and the national economy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80b-1?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§80b–1. Findings","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 80b-13","url":"https://www.law.cornell.edu/uscode/text/15/80b-13","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 80b-4","url":"https://www.law.cornell.edu/uscode/text/15/80b-4","stext":{"head":"§80b–4. Reports by investment advisers","paras":[[0,"(a) In general"],[0,"Every investment adviser who makes use of the mails or of any means or instrumentality of interstate commerce in connection with his or its business as an investment adviser (other than one specifically exempted from registration pursuant to section 80b–3(b) of this title), shall make and keep for prescribed periods such records (as defined in section 78c(a)(37) of this title), furnish such copies thereof, and make and disseminate such reports as the Commission, by rule, may prescribe as necessary or appropriate in the public interest or for the protection of investors. All records (as so defined) of such investment advisers are subject at any time, or from time to time, to such reasonable periodic, special, or other examinations by representatives of the Commission as the Commission deems necessary or appropriate in the public interest or for the protection of investors."],[0,"(b) Records and reports of private funds"],[0,"(1) In general"],[1,"The Commission may require any investment adviser registered under this subchapter—"],[2,"(A) to maintain such records of, and file with the Commission such reports regarding, private funds advised by the investment adviser, as necessary and appropriate in the public interest and for the protection of investors, or for the assessment of systemic risk by the Financial Stability Oversight Council (in this subsection referred to as the \"Council\"); and"],[2,"(B) to provide or make available to the Council those reports or records or the information contained therein."],[0,"(2) Treatment of records"],[1,"The records and reports of any private fund to which an investment adviser registered under this subchapter provides investment advice shall be deemed to be the records and reports of the investment adviser."],[0,"(3) Required information"],[1,"The records and reports required to be maintained by an investment adviser and subject to inspection by the Commission under this subsection shall include, for each private fund advised by the investment adviser, a description of—"],[2,"(A) the amount of assets under management and use of leverage, including off-balance-sheet leverage;"],[2,"(B) counterparty credit risk exposure;"],[2,"(C) trading and investment positions;"],[2,"(D) valuation policies and practices of the fund;"],[2,"(E) types of assets held;"],[2,"(F) side arrangements or side letters, whereby certain investors in a fund obtain more favorable rights or entitlements than other investors;"],[2,"(G) trading practices; and"],[2,"(H) such other information as the Commission, in consultation with the Council, determines is necessary and appropriate in the public interest and for the protection of investors or for the assessment of systemic risk, which may include the establishment of different reporting requirements for different classes of fund advisers, based on the type or size of private fund being advised."],[0,"(4) Maintenance of records"],[1,"An investment adviser registered under this subchapter shall maintain such records of private funds advised by the investment adviser for such period or periods as the Commission, by rule, may prescribe as necessary and appropriate in the public interest and for the protection of investors, or for the assessment of systemic risk."],[0,"(5) Filing of records"],[1,"The Commission shall issue rules requiring each investment adviser to a private fund to file reports containing such information as the Commission deems necessary and appropriate in the public interest and for the protection of investors or for the assessment of systemic risk."],[0,"(6) Examination of records"],[0,"(A) Periodic and special examinations"],[2,"The Commission—"],[3,"(i) shall conduct periodic inspections of the records of private funds maintained by an investment adviser registered under this subchapter in accordance with a schedule established by the Commission; and"],[3,"(ii) may conduct at any time and from time to time such additional, special, and other examinations as the Commission may prescribe as necessary and appropriate in the public interest and for the protection of investors, or for the assessment of systemic risk."],[0,"(B) Availability of records"],[2,"An investment adviser registered under this subchapter shall make available to the Commission any copies or extracts from such records as may be prepared without undue effort, expense, or delay, as the Commission or its representatives may reasonably request."],[0,"(7) Information sharing"],[0,"(A) In general"],[2,"The Commission shall make available to the Council copies of all reports, documents, records, and information filed with or provided to the Commission by an investment adviser under this subsection as the Council may consider necessary for the purpose of assessing the systemic risk posed by a private fund."],[0,"(B) Confidentiality"],[2,"The Council shall maintain the confidentiality of information received under this paragraph in all such reports, documents, records, and information, in a manner consistent with the level of confidentiality established for the Commission pursuant to paragraph (8). The Council shall be exempt from section 552 of title 5 with respect to any information in any report, document, record, or information made available, to the Council under this subsection.\".1"],[0,"(8) Commission confidentiality of reports"],[1,"Notwithstanding any other provision of law, the Commission may not be compelled to disclose any report or information contained therein required to be filed with the Commission under this subsection, except that nothing in this subsection authorizes the Commission—"],[2,"(A) to withhold information from Congress, upon an agreement of confidentiality; or"],[2,"(B) prevent 2 the Commission from complying with—"],[3,"(i) a request for information from any other Federal department or agency or any self-regulatory organization requesting the report or information for purposes within the scope of its jurisdiction; or"],[3,"(ii) an order of a court of the United States in an action brought by the United States or the Commission."],[0,"(9) Other recipients confidentiality"],[1,"Any department, agency, or self-regulatory organization that receives reports or information from the Commission under this subsection shall maintain the confidentiality of such reports, documents, records, and information in a manner consistent with the level of confidentiality established for the Commission under paragraph (8)."],[0,"(10) Public information exception"],[0,"(A) In general"],[2,"The Commission, the Council, and any other department, agency, or self-regulatory organization that receives information, reports, documents, records, or information from the Commission under this subsection, shall be exempt from the provisions of section 552 of title 5 with respect to any such report, document, record, or information. Any proprietary information of an investment adviser ascertained by the Commission from any report required to be filed with the Commission pursuant to this subsection shall be subject to the same limitations on public disclosure as any facts ascertained during an examination, as provided by section 80b–10(b) of this title."],[0,"(B) Proprietary information"],[2,"For purposes of this paragraph, proprietary information includes sensitive, non-public information regarding—"],[3,"(i) the investment or trading strategies of the investment adviser;"],[3,"(ii) analytical or research methodologies;"],[3,"(iii) trading data;"],[3,"(iv) computer hardware or software containing intellectual property; and"],[3,"(v) any additional information that the Commission determines to be proprietary."],[0,"(11) Annual report to Congress"],[1,"The Commission shall report annually to Congress on how the Commission has used the data collected pursuant to this subsection to monitor the markets for the protection of investors and the integrity of the markets."],[0,"(c) Filing depositories"],[0,"The Commission may, by rule, require an investment adviser—"],[1,"(1) to file with the Commission any fee, application, report, or notice required to be filed by this subchapter or the rules issued under this subchapter through any entity designated by the Commission for that purpose; and"],[1,"(2) to pay the reasonable costs associated with such filing and the establishment and maintenance of the systems required by subsection (c)."],[0,"(d) Access to disciplinary and other information"],[0,"(1) Maintenance of system to respond to inquiries"],[0,"(A) In general"],[2,"The Commission shall require the entity designated by the Commission under subsection (b)(1) to establish and maintain a toll-free telephone listing, or a readily accessible electronic or other process, to receive and promptly respond to inquiries regarding registration information (including disciplinary actions, regulatory, judicial, and arbitration proceedings, and other information required by law or rule to be reported) involving investment advisers and persons associated with investment advisers."],[0,"(B) Applicability"],[2,"This subsection shall apply to any investment adviser (and the persons associated with that adviser), whether the investment adviser is registered with the Commission under section 80b–3 of this title or regulated solely by a State, as described in section 80b–3a of this title."],[0,"(2) Recovery of costs"],[1,"An entity designated by the Commission under subsection (b)(1) may charge persons making inquiries, other than individual investors, reasonable fees for responses to inquiries described in paragraph (1)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80b-4?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§80b–4. Reports by investment advisers","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 78o","url":"https://www.law.cornell.edu/uscode/text/15/78o","subs":["(b)(7)"],"by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 80b-6","url":"https://www.law.cornell.edu/uscode/text/15/80b-6","stext":{"head":"§80b–6. Prohibited transactions by investment advisers","paras":[[0,"It shall be unlawful for any investment adviser by use of the mails or any means or instrumentality of interstate commerce, directly or indirectly—"],[1,"(1) to employ any device, scheme, or artifice to defraud any client or prospective client;"],[1,"(2) to engage in any transaction, practice, or course of business which operates as a fraud or deceit upon any client or prospective client;"],[1,"(3) acting as principal for his own account, knowingly to sell any security to or purchase any security from a client, or acting as broker for a person other than such client, knowingly to effect any sale or purchase of any security for the account of such client, without disclosing to such client in writing before the completion of such transaction the capacity in which he is acting and obtaining the consent of the client to such transaction. The prohibitions of this paragraph shall not apply to any transaction with a customer of a broker or dealer if such broker or dealer is not acting as an investment adviser in relation to such transaction; or"],[1,"(4) to engage in any act, practice, or course of business which is fraudulent, deceptive, or manipulative. The Commission shall, for the purposes of this paragraph (4) by rules and regulations define, and prescribe means reasonably designed to prevent, such acts, practices, and courses of business as are fraudulent, deceptive, or manipulative."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/80b-6?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§80b–6. Prohibited transactions by investment advisers","tname":"Commerce and Trade","by":{"0":""}}]};